import zipfile, pathlib, xml.etree.ElementTree as ET, re
from html import unescape
root=pathlib.Path('workspace')
for p in sorted(root.rglob('*')):
 if not p.is_file(): continue
 s=''
 try:
  if p.suffix=='.txt': s=p.read_text(errors='replace')
  elif p.suffix=='.docx':
   with zipfile.ZipFile(p) as z:
    for n in ['word/document.xml','word/footnotes.xml','word/endnotes.xml']:
     if n in z.namelist():
      t=ET.fromstring(z.read(n)); s+=' '.join(x.text or '' for x in t.iter() if x.tag.endswith('}t'))+' '
  elif p.suffix=='.xlsx':
   with zipfile.ZipFile(p) as z:
    ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    shared=[]
    if 'xl/sharedStrings.xml' in z.namelist():
     t=ET.fromstring(z.read('xl/sharedStrings.xml')); shared=[''.join(x.text or '' for x in si.iter() if x.tag.endswith('}t')) for si in t]
    for n in z.namelist():
     if re.fullmatch(r'xl/worksheets/sheet\\d+\\.xml',n):
      t=ET.fromstring(z.read(n))
      for c in t.iter('{%s}c'%ns['m']):
       v=c.find('{%s}v'%ns['m']); val='' if v is None else v.text or ''
       if c.get('t')=='s' and val: val=shared[int(val)]
       if val: s+=val+' | '
  elif p.suffix=='.pdf':
   import subprocess
   r=subprocess.run(['pdftotext',str(p),'-'],capture_output=True,text=True)
   s=r.stdout or '[NO EXTRACTABLE TEXT]'
 except Exception as e: s='[EXTRACTION ERROR '+str(e)+']'
 print('\\n###',p.as_posix()); print(s[:5000])
PY"

